<template><div class="create-post-page"><div class="create-post-card"><h2>{{t('createPost')}}</h2><form class="create-post-form" @submit.prevent="submit"><div class="create-post-field"><label>{{t('category')}}</label><select v-model.number="categoryIdx"><option v-for="(key,i) in categoryKeys" :key="key" :value="i">{{t(key)}}</option></select></div><div class="create-post-field"><label>{{t('title')}}</label><input v-model="title" :placeholder="t('titlePlaceholder')" required></div><div class="create-post-field"><label>{{t('content')}}</label><textarea ref="textarea" v-model="content" :placeholder="t('contentPlaceholder')" required></textarea><div class="create-post-emoji-bar"><EmojiPicker @select="insert"/><button type="button" class="emoji-picker-trigger" :disabled="uploading" @click="fileInput?.click()">{{t('imageBtn') || '图片'}}</button><input ref="fileInput" type="file" hidden accept="image/png,image/jpeg,image/gif,image/webp" @change="upload"></div><div v-if="uploading" class="create-post-uploading-hint">{{t('uploadingImage')}}</div></div><div class="create-post-actions"><button class="create-post-submit" :disabled="loading">{{loading?t('publishing'):t('publish')}}</button><button type="button" class="create-post-cancel" @click="leave">{{t('cancel')}}</button></div></form></div></div></template><script setup>import {onMounted,ref,watch} from 'vue';import {useRouter} from 'vue-router';import {useLang} from '../contexts/app';import {postService} from '../services/postService';import EmojiPicker from '../components/EmojiPicker.vue';const router=useRouter();const {t}=useLang();const categoryKeys=['catDiscussion','catExplore','catParanormal','catHelp','catShare','catLive','catOC'],categoryValues=['讨论','探灵','灵异','求助','分享','语c','OC投稿'];const title=ref(''),content=ref(''),categoryIdx=ref(0),loading=ref(false),uploading=ref(false),textarea=ref(null),fileInput=ref(null);onMounted(()=>{try{const d=JSON.parse(sessionStorage.getItem('create_post_draft')||'null');if(d){title.value=d.title||'';content.value=d.content||'';categoryIdx.value=d.categoryIdx||0}}catch{}});watch([title,content,categoryIdx],()=>{if(title.value.trim()||content.value.trim())sessionStorage.setItem('create_post_draft',JSON.stringify({title:title.value,content:content.value,categoryIdx:categoryIdx.value}));else sessionStorage.removeItem('create_post_draft')});const insert=x=>{const el=textarea.value;const s=el?.selectionStart??content.value.length,e=el?.selectionEnd??s;content.value=content.value.slice(0,s)+x+content.value.slice(e)};const upload=async e=>{const file=e.target.files?.[0];if(!file)return;uploading.value=true;try{insert(`\n[img:${(await postService.uploadImage(file)).url}]\n`)}catch{alert(t('uploadFailed'))}finally{uploading.value=false;e.target.value=''}};const leave=()=>{if(!title.value.trim()&&!content.value.trim())router.back();else if(confirm(t('leaveEditorConfirm')))router.back()};const submit=async()=>{loading.value=true;try{const m=content.value.match(/\[img:([^\]]+)\]/);await postService.createPost({title:title.value,category:categoryValues[categoryIdx.value],content:content.value,image_url:m?m[1]:null});sessionStorage.removeItem('create_post_draft');router.push('/')}catch{alert(t('postFailed'))}finally{loading.value=false}};</script>
